use cagents::process::{
    CancellationToken, CommandSpec, ProcessExecutor, ProcessOutput, SystemProcessExecutor,
};
use serde_json::{Value, json};
use std::{
    fs,
    os::unix::fs::PermissionsExt,
    path::Path,
    process::{Command, Stdio},
    time::Duration,
};

const ISSUE_ID: &str = "2b498c52-7dc7-4c76-ad59-dfc488c40111";
const TEAM_ID: &str = "2b498c52-7dc7-4c76-ad59-dfc488c40222";
const KEY: &str = "fixture-linear-secret";
// Let the production keyring's 15-second deadline report its own error before
// this independent guard terminates a stuck CLI and its process group.
const COMMAND_TIMEOUT: Duration = Duration::from_secs(22);
const OUTPUT_LIMIT: usize = 1024 * 1024;

fn isolated(mut command: CommandSpec) -> CommandSpec {
    // Keep the invoking agent's authority unchanged while excluding host tools,
    // credentials, Git overrides and configuration from private fixtures.
    for (name, _) in std::env::vars_os() {
        if name != std::ffi::OsStr::new(cagents::agent_execution::AUTHORITY_ENV) {
            command = command.env_remove(name);
        }
    }
    command
        .timeout(COMMAND_TIMEOUT)
        .output_limits(OUTPUT_LIMIT, OUTPUT_LIMIT)
}

fn capture(command: CommandSpec) -> ProcessOutput {
    SystemProcessExecutor
        .execute(&command, &CancellationToken::new())
        .unwrap_or_else(|error| panic!("bounded fixture process failed: {error:?}"))
}

struct Fixture {
    root: tempfile::TempDir,
}
impl Fixture {
    fn new() -> Self {
        let root = tempfile::tempdir().unwrap();
        fs::create_dir(root.path().join("bin")).unwrap();
        fs::write(
            root.path().join("bin/curl"),
            include_bytes!("fixtures/linear-curl.sh"),
        )
        .unwrap();
        fs::set_permissions(
            root.path().join("bin/curl"),
            fs::Permissions::from_mode(0o700),
        )
        .unwrap();
        // Missing-key behavior must not depend on a CI host's Secret Service
        // installation or desktop environment. Specific keyring tests replace it.
        let keyring = root.path().join("bin/secret-tool");
        fs::write(&keyring, "#!/bin/sh\nexit 1\n").unwrap();
        fs::set_permissions(&keyring, fs::Permissions::from_mode(0o700)).unwrap();
        let f = Self { root };
        let output = capture(
            isolated(CommandSpec::new("git"))
                .args(["init", "-q", "--template="])
                .cwd(f.path())
                .env("HOME", f.path())
                .env("PATH", "/usr/bin:/bin")
                .env("GIT_CONFIG_GLOBAL", "/dev/null")
                .env("GIT_CONFIG_SYSTEM", "/dev/null")
                .env("GIT_CONFIG_NOSYSTEM", "1"),
        );
        assert!(output.success, "{output:?}");
        f.read(json!({"issue":{
            "id": ISSUE_ID,"identifier":"ENG-12","title":"Fixture issue","description":"Body",
            "team":{"id":TEAM_ID,"key":"ENG"}, "state":{"id":TEAM_ID,"name":"In Progress","type":"started"},
            "labels":{"nodes":[],"pageInfo":{"hasNextPage":false,"endCursor":null}},
            "comments":{"nodes":[],"pageInfo":{"hasNextPage":false,"endCursor":null}}
        }}));
        f.mutation(
            json!({"issueUpdate":{"success":true,"issue":{"id":ISSUE_ID,"title":"Updated"}},
            "issueCreate":{"success":true,"issue":{"id":ISSUE_ID}},
            "commentCreate":{"success":true,"comment":{"id":TEAM_ID,"body":"Done"}}}),
        );
        f
    }
    fn path(&self) -> &Path {
        self.root.path()
    }
    fn read(&self, data: Value) {
        fs::write(self.path().join("read"), json!({"data":data}).to_string()).unwrap();
    }
    fn mutation(&self, data: Value) {
        fs::write(
            self.path().join("mutation"),
            json!({"data":data}).to_string(),
        )
        .unwrap();
    }
    fn command(&self, args: &[&str]) -> CommandSpec {
        isolated(CommandSpec::new(env!("CARGO_BIN_EXE_cagents")))
            .env("HOME", self.path())
            .env(
                "PATH",
                format!("{}:/usr/bin:/bin", self.path().join("bin").display()),
            )
            .env("LINEAR_FIXTURE", self.path())
            .env("LINEAR_API_KEY", KEY)
            .env("CAGENTS_LINEAR_API_KEY_WORK", KEY)
            .cwd(self.path())
            .arg("--json")
            .args(args.iter().copied())
    }
    fn without_api_key(&self, args: &[&str]) -> CommandSpec {
        let mut command = self.command(args);
        // CommandSpec applies removals before explicit overrides. Remove the
        // fixture override too so these tests really exercise the keyring.
        command
            .environment
            .remove(std::ffi::OsStr::new("LINEAR_API_KEY"));
        command.env_remove("LINEAR_API_KEY")
    }
    fn run(&self, args: &[&str]) -> ProcessOutput {
        capture(self.command(args))
    }
    fn success(&self, args: &[&str]) -> Value {
        let o = self.run(args);
        assert!(
            o.success,
            "{args:?}: {}",
            String::from_utf8_lossy(&o.stderr)
        );
        let v: Value = serde_json::from_slice(&o.stdout).unwrap();
        assert_eq!(v["ok"], true);
        v["data"].clone()
    }
    fn failure(&self, args: &[&str]) -> Value {
        let o = self.run(args);
        assert!(!o.success, "{args:?}");
        assert!(!String::from_utf8_lossy(&o.stderr).contains(KEY));
        serde_json::from_slice::<Value>(&o.stderr).unwrap()["error"].clone()
    }
    fn request(&self) -> String {
        fs::read_to_string(self.path().join("request")).unwrap()
    }
#[test]
fn issue_context_connections_are_pageable() {
    let f = Fixture::new();
    f.read(
        json!({"issue":{"comments":{"nodes":[{"id":ISSUE_ID,"body":"Markdown"}],
        "pageInfo":{"hasNextPage":true,"endCursor":"more-comments"}}}}),
    );
    let result = f.success(&[
        "linear", "comments", "--id", "ENG-12", "--limit", "1", "--cursor", "previous",
    ]);
    assert_eq!(result["nodes"][0]["body"], "Markdown");
    assert_eq!(result["pageInfo"]["endCursor"], "more-comments");
    assert!(f.request().contains("previous"));

    // Exercise the real command names and stdout writer as well as JSON mode.
    // The existing fixture curl reads these responses without contacting Linear.
    let long_text = "Complete **Markdown** text\nwith another line ".repeat(20);
    for (operation, field, node) in [
        (
            "comments",
            "comments",
            json!({"id": ISSUE_ID, "body": long_text,
                "user": {"id": TEAM_ID, "name": "Comment author"}}),
        ),
        (
            "relations",
            "relations",
            json!({"id": ISSUE_ID, "type": "related",
                "issue": {"identifier": "ENG-12", "title": "Original issue"},
                "relatedIssue": {"identifier": "ENG-13", "title": "Related issue"}}),
        ),
        (
            "children",
            "children",
            json!({"id": ISSUE_ID, "identifier": "ENG-13", "description": long_text}),
        ),
        (
            "relations",
            "inverseRelations",
            json!({"id": ISSUE_ID, "type": "blocks",
                "issue": {"identifier": "ENG-14", "title": "Incoming issue"},
                "relatedIssue": {"identifier": "ENG-12", "title": "Original issue"}}),
        ),
    ] {
        let mut args = vec!["linear", operation, "--id", ISSUE_ID];
        if field == "inverseRelations" {
            args.push("--inverse");
